const AR=Object.fromEntries(Object.entries(EN).map(([a,b])=>[b,a]));
function isEnglish(){return db.settings?.language==='en'}
function setLanguage(lang){db.settings.language=lang==='en'?'en':'ar';saveDB();render();applyLocale();}
function savePreferences(){db.settings.theme=document.getElementById('appTheme')?.value==='dark'?'dark':'light';db.settings.fontScale=Math.max(90,Math.min(115,Number(document.getElementById('fontScale')?.value)||100));db.settings.backupReminderDays=Math.max(1,Math.min(90,Number(document.getElementById('backupReminderDays')?.value)||7));saveDB();render();toast('تم حفظ تفضيلات النظام');}
function checkBackupReminder(){const days=Math.max(1,Number(db.settings.backupReminderDays)||7),last=db.settings.lastBackupAt?new Date(db.settings.lastBackupAt).getTime():0;if(!last||Date.now()-last>=days*86400000)toast('تذكير: حان وقت تنزيل نسخة احتياطية من بيانات الورشة');}
function backupStatusText(){if(!db.settings.lastBackupAt)return 'لم يتم تنزيل نسخة احتياطية بعد';const d=new Date(db.settings.lastBackupAt);return Number.isNaN(d.getTime())?'لم يتم تنزيل نسخة احتياطية بعد':'آخر نسخة احتياطية: '+d.toLocaleString('ar-QA');}
function dataOverview(){const names={customers:'العملاء',projects:'المشاريع',quotes:'عروض الأسعار',invoices:'الفواتير',inventory:'أصناف المخزون',expenses:'المصروفات',purchases:'المشتريات',production:'أوامر التصنيع',installations:'عمليات التركيب'};return Object.entries(names).map(([k,v])=>`<div class="settings-metric"><span>${v}</span><strong>${(db[k]||[]).length}</strong></div>`).join('');}
function exportAllCSV(){const keys=['customers','projects','quotes','invoices','inventory','expenses','purchases','production','installations'].filter(k=>(db[k]||[]).length);if(!keys.length){toast('لا توجد بيانات للتصدير');return}keys.forEach((k,i)=>setTimeout(()=>exportCSV(k),i*700));toast('بدأ تصدير الجداول؛ قد يطلب المتصفح السماح بتنزيل عدة ملفات')}
function applyLocale(){const en=isEnglish(),dict=en?EN:AR,root=document.documentElement;root.lang=en?'en':'ar';root.dir=en?'ltr':'rtl';document.body.classList.toggle('english-ui',en);const title=document.getElementById('pageTitle');if(title)title.textContent=dict[pageTitle(currentPage)]||pageTitle(currentPage);const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){const raw=n.nodeValue,trim=raw.trim();if(dict[trim])n.nodeValue=raw.replace(trim,dict[trim]);}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(a=>{const v=el.getAttribute(a);if(v&&dict[v])el.setAttribute(a,dict[v]);}));}

function render(){document.body.dataset.page=currentPage;const el=document.getElementById('content');const map={dashboard:dashboardPage,customers:customersPage,projects:projectsPage,quotes:quotesPage,production:productionPage,inventory:inventoryPage,purchases:purchasesPage,installations:installationsPage,invoices:invoicesPage,expenses:expensesPage,reports:reportsPage,settings:settingsPage};el.innerHTML=(map[currentPage]||dashboardPage)();applyLocale()}
function dashboardPage(){
 const open=db.production.filter(x=>!['مكتمل','ملغي'].includes(x.status)).length, unpaid=db.invoices.reduce((s,x)=>s+Math.max(0,(+x.total||0)-(+x.paid||0)),0), stockLow=db.inventory.filter(x=>(+x.qty||0)<=(+x.min||0)).length, revenue=db.invoices.reduce((s,x)=>s+(+x.paid||0),0), expenses=db.expenses.reduce((s,x)=>s+(+x.amount||0),0);
 const recent=[...db.projects].slice(-5).reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.name)}</span><span class="sub-cell">${esc(p.code||p.id)}</span></td><td>${esc(customerName(p.customerId))}</td><td>${esc(p.type||'—')}</td><td>${badge(p.status||'جديد')}</td><td>${money(p.total)}</td></tr>`).join('');
 return head('مرحبًا بك في ForgePro','نظرة عامة على أداء الورشة وحالة المشاريع اليوم',btn('＋ مشروع جديد',"openForm('project')"))+
 `<div class="stats-grid">${stat('المبالغ المحصلة',money(revenue),'↗','إجمالي الدفعات المسجلة')}${stat('أوامر التصنيع المفتوحة',open,'⚒','تحتاج إلى متابعة')}${stat('المبالغ المستحقة',money(unpaid),'ر.ق','حسب الفواتير المسجلة')}${stat('تنبيهات المخزون',stockLow,'▥','أصناف عند الحد الأدنى أو أقل')}</div>
 <div class="dashboard-grid"><div><div class="panel"><div class="panel-head"><div><h3>أحدث المشاريع</h3><p>آخر المشاريع المسجلة في النظام</p></div>${btn('عرض الكل',"setPage('projects')",'btn-light btn-small')}</div>${recent?table(['المشروع','العميل','نوع العمل','الحالة','القيمة'],recent):empty('أضف أول مشروع لتبدأ إدارة أعمال الورشة')}</div>
 <div class="panel"><div class="panel-head"><div><h3>إجراءات سريعة</h3><p>ابدأ العمل دون التنقل بين الأقسام</p></div></div><div class="panel-body"><div class="quick-grid"><button class="quick-tile" onclick="openForm('customer')"><span>♙</span><b>إضافة عميل</b><small>تسجيل عميل جديد</small></button><button class="quick-tile" onclick="openForm('project')"><span>▤</span><b>مشروع جديد</b><small>تسجيل القياسات والتكلفة</small></button><button class="quick-tile" onclick="openForm('inventory')"><span>▥</span><b>إضافة مادة</b><small>تحديث المخزون</small></button><button class="quick-tile" onclick="openForm('quote')"><span>▧</span><b>عرض سعر</b><small>إنشاء تسعير للعميل</small></button><button class="quick-tile" onclick="openForm('production')"><span>⚒</span><b>أمر تصنيع</b><small>بدء متابعة الإنتاج</small></button><button class="quick-tile" onclick="openForm('invoice')"><span>▣</span><b>فاتورة جديدة</b><small>إنشاء فاتورة للعميل</small></button></div></div></div></div>
 <div><div class="panel"><div class="panel-head"><div><h3>حالة الإنتاج</h3><p>توزيع أوامر التصنيع الحالية</p></div></div><div class="panel-body">${productionBars()}</div></div><div class="panel"><div class="panel-head"><div><h3>ملخص مالي</h3><p>المبالغ المسجلة في النظام</p></div></div><div class="panel-body"><div class="bar-row"><div class="bar-meta"><span>المقبوضات</span><span>${money(revenue)}</span></div><div class="progress"><span style="width:${Math.min(100,revenue/(revenue+expenses+1)*100)}%"></span></div></div><div class="bar-row"><div class="bar-meta"><span>المصروفات</span><span>${money(expenses)}</span></div><div class="progress"><span style="width:${Math.min(100,expenses/(revenue+expenses+1)*100)}%;background:#d65353"></span></div></div><div class="bar-row"><div class="bar-meta"><span>مستحقات العملاء</span><span>${money(unpaid)}</span></div><div class="progress"><span style="width:${Math.min(100,unpaid/(revenue+unpaid+1)*100)}%;background:#477bd4"></span></div></div></div></div><div class="notice">تذكير: خذ نسخة احتياطية دورية من صفحة الإعدادات، لأن بيانات هذا الإصدار محفوظة على المتصفح والجهاز الحالي.</div></div></div>`
}
function productionBars(){if(!db.production.length)return empty('لا توجد أوامر تصنيع');const statuses=['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل'];return statuses.map((s,i)=>{let n=db.production.filter(x=>x.status===s).length;return `<div class="bar-row"><div class="bar-meta"><span>${s}</span><span>${n}</span></div><div class="progress"><span style="width:${n/Math.max(1,db.production.length)*100}%;background:${['#d5a04c','#477bd4','#e5a23b','#9b79ce','#2c9c80','#4d8ed8','#169b72'][i]}"></span></div></div>`}).join('')}
function customersPage(){let rows=db.customers.slice().reverse().map(c=>`<tr><td><span class="primary-cell">${esc(c.name)}</span><span class="sub-cell">${esc(c.code||'')}</span></td><td>${esc(c.phone||'—')}</td><td>${esc(c.type||'فرد')}</td><td>${esc(c.address||'—')}</td><td>${db.projects.filter(p=>p.customerId===c.id).length}</td><td>${btn('تعديل',`editItem('customer','${c.id}')`,'btn-light btn-small')} ${btn('حذف',`deleteItem('customers','${c.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('العملاء','إدارة بيانات العملاء والمقاولين وسجل مشاريعهم',btn('＋ إضافة عميل',"openForm('customer')"))+`<div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث بالاسم أو الهاتف..." oninput="filterRows(this,0)"><span class="badge">${db.customers.length} عميل</span></div><div id="customerTable">${rows?table(['العميل','الهاتف','نوع العميل','العنوان','المشاريع','الإجراءات'],rows):empty('لا يوجد عملاء. أضف أول عميل.')}</div></div></div>`}
function projectsPage(){let rows=db.projects.slice().reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.name)}</span><span class="sub-cell">${esc(p.code||p.id)}</span></td><td>${esc(customerName(p.customerId))}</td><td>${esc(p.type||'—')}</td><td>${p.width&&p.height?`${p.width} × ${p.height} ${esc(p.unit||'سم')}`:'متعدد'}</td><td>${esc(p.qty||1)}</td><td>${badge(p.status||'جديد')}</td><td>${money(p.total)}</td><td>${btn('تعديل',`editItem('project','${p.id}')`,'btn-light btn-small')} ${btn('حذف',`deleteItem('projects','${p.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('المشاريع والقياسات','تسجيل أعمال الحدادة والألمنيوم وحساب المساحات والكميات',btn('＋ مشروع جديد',"openForm('project')"))+`<div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث باسم المشروع أو العميل..." oninput="filterRows(this,0)"><span class="badge">${db.projects.length} مشروع</span></div>${rows?table(['المشروع','العميل','نوع العمل','المقاس','العدد','الحالة','القيمة','الإجراءات'],rows):empty('لا توجد مشاريع مسجلة بعد.')}</div></div>`}
function quotesPage(){
 const quotes=db.quotes.slice().reverse();
 const count=status=>quotes.filter(q=>(q.status||'مسودة')===status).length;
 const totalValue=quotes.reduce((sum,q)=>sum+(Number(q.total)||0),0);
 const rows=quotes.map(q=>{
  const status=q.status||'مسودة';
  const work=Object.keys(q).filter(k=>/^title\d*$/.test(k)).sort((a,b)=>{const n=x=>x==='title'?1:Number(x.slice(5));return n(a)-n(b)}).map(k=>q[k]).filter(Boolean).join('، ');
  const searchText=[q.code,customerName(q.customerId),work,status,q.date].join(' ').toLowerCase();
  const statusAction=status==='معتمد'?btn('إلغاء الاعتماد',`cancelQuoteApproval('${q.id}')`,'btn-light btn-small'):btn('اعتماد',`approveQuote('${q.id}')`,'btn-approve btn-small');
  return `<tr class="quote-row" data-status="${esc(status)}" data-search="${esc(searchText)}">
   <td><span class="primary-cell quote-code">${esc(q.code||'—')}</span><span class="sub-cell">${esc(q.date||'—')}</span></td>
   <td><span class="primary-cell">${esc(customerName(q.customerId))}</span><span class="sub-cell quote-work-summary">${esc(work||'—')}</span></td>
   <td>${badge(status)}</td><td class="quote-amount">${money(q.total)}</td>
   <td><div class="quote-row-actions">${btn('تعديل',`editItem('quote','${q.id}')`,'btn-primary btn-small')} ${btn('طباعة / PDF',`printQuote('${q.id}')`,'btn-light btn-small')} ${statusAction}<button class="quote-delete" title="حذف العرض" aria-label="حذف العرض" onclick="deleteItem('quotes','${q.id}')">حذف</button></div></td>
  </tr>`;
 }).join('');
 return `<section class="document-management-page quotes-management">`+head('عروض الأسعار','أنشئ عروض الأسعار، تابع اعتمادها، وراجع قيمتها وحالتها بسهولة.',btn('＋ عرض سعر جديد',"openForm('quote')"))+
 `<div class="document-kpi-grid quote-summary">
  <article class="quote-summary-card"><span>إجمالي العروض</span><strong>${quotes.length}</strong><small>جميع عروض الأسعار المسجلة</small></article>
  <article class="quote-summary-card"><span>مسودات</span><strong>${count('مسودة')}</strong><small>تحتاج إلى مراجعة أو إرسال</small></article>
  <article class="quote-summary-card"><span>عروض معتمدة</span><strong>${count('معتمد')}</strong><small>تم اعتمادها</small></article>
  <article class="quote-summary-card"><span>إجمالي قيمة العروض</span><strong>${money(totalValue)}</strong><small>قيمة جميع العروض المسجلة</small></article>
 </div>
 <div class="panel quote-list-panel document-list-panel"><div class="panel-head"><div><h3>سجل عروض الأسعار</h3><p>ابحث عن عرض، صفِّ النتائج، أو نفّذ الإجراء المطلوب.</p></div><span class="document-count-pill">${quotes.length} عرض</span></div><div class="panel-body"><div class="quote-toolbar document-toolbar"><div class="quote-search-wrap"><span>⌕</span><input id="quoteSearch" class="field" placeholder="ابحث برقم العرض أو اسم العميل أو وصف العمل" oninput="filterQuoteCards()" aria-label="البحث في عروض الأسعار"></div><select id="quoteStatusFilter" class="field quote-status-filter" onchange="filterQuoteCards()" aria-label="تصفية حالة العرض"><option value="">كل الحالات</option><option>مسودة</option><option>مرسل للعميل</option><option>معتمد</option><option>مرفوض</option></select><span class="quote-result-count" id="quoteResultCount">${quotes.length} عرض</span></div>
 ${rows?`<div class="table-wrap quote-table-wrap"><table class="quote-list-table document-list-table"><thead><tr><th>رقم العرض / التاريخ</th><th>العميل / تفاصيل العمل</th><th>الحالة</th><th>الإجمالي</th><th>الإجراءات</th></tr></thead><tbody id="quoteCardGrid">${rows}</tbody></table></div><div class="empty-state quote-no-results" id="quoteNoResults" hidden>لا توجد عروض مطابقة للبحث أو التصفية.</div>`:empty('لا توجد عروض أسعار مسجلة. أنشئ أول عرض للبدء.')}</div></div></section>`;
}
function filterQuoteCards(){const search=(document.getElementById('quoteSearch')?.value||'').trim().toLowerCase(),status=document.getElementById('quoteStatusFilter')?.value||'';const rows=[...document.querySelectorAll('.quote-row')];let shown=0;rows.forEach(row=>{const match=(!search||(row.dataset.search||'').includes(search))&&(!status||row.dataset.status===status);row.hidden=!match;if(match)shown++});const count=document.getElementById('quoteResultCount');if(count)count.textContent=`${shown} عرض`;const empty=document.getElementById('quoteNoResults');if(empty)empty.hidden=shown!==0||rows.length===0}

function productionPage(){let rows=db.production.slice().reverse().map(p=>`<tr><td><span class="primary-cell">${esc(p.code)}</span></td><td>${esc(projectName(p.projectId))}</td><td>${esc(p.stage||'تصنيع')}</td><td>${esc(p.worker||'—')}</td><td>${esc(p.due||'—')}</td><td>${badge(p.status||'جديد')}</td><td><select class="field" style="min-width:140px;padding:6px" onchange="changeStatus('production','${p.id}',this.value)">${['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل','ملغي'].map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('');return head('أوامر التصنيع','متابعة مراحل القص والتجميع والتشطيب والفحص',btn('＋ أمر تصنيع',"openForm('production')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الأمر','المشروع','المرحلة','المسؤول','موعد التسليم','الحالة','تحديث الحالة'],rows):empty('لا توجد أوامر تصنيع. أنشئ أمرًا من مشروع قائم.')}</div></div>`}
function inventoryPage(){let rows=db.inventory.slice().reverse().map(i=>`<tr><td><span class="primary-cell">${esc(i.name)}</span><span class="sub-cell">${esc(i.code||'')}</span></td><td>${esc(i.category||'مواد خام')}</td><td>${esc(i.unit||'قطعة')}</td><td>${esc(i.qty)}</td><td>${esc(i.min||0)}</td><td>${money(i.cost)}</td><td>${money((+i.qty||0)*(+i.cost||0))}</td><td>${(+i.qty||0)<=(+i.min||0)?badge('مخزون منخفض'):badge('متوفر')}</td><td>${btn('تعديل',`editItem('inventory','${i.id}')`,'btn-light btn-small')} ${btn('حركة',`stockMovement('${i.id}')`,'btn-primary btn-small')}</td></tr>`).join('');return head('المخزون والمواد','إدارة القطاعات والحديد والزجاج والإكسسوارات والهالك',btn('＋ إضافة مادة',"openForm('inventory')"))+`<div class="stats-grid">${stat('عدد الأصناف',db.inventory.length,'▥')}${stat('قيمة المخزون',money(db.inventory.reduce((s,x)=>s+(+x.qty||0)*(+x.cost||0),0)),'ر.ق')}${stat('أصناف منخفضة',db.inventory.filter(x=>(+x.qty||0)<=(+x.min||0)).length,'!')}${stat('وحدات المخزون',db.inventory.reduce((s,x)=>s+(+x.qty||0),0).toLocaleString('en-US'),'▤')}</div><div class="panel"><div class="panel-body"><div class="search-row"><input class="field search-input" placeholder="ابحث عن مادة أو كود..." oninput="filterRows(this,0)"></div>${rows?table(['الصنف','الفئة','الوحدة','الكمية','حد التنبيه','تكلفة الوحدة','قيمة المخزون','الحالة','الإجراءات'],rows):empty('أضف المواد الخام والأصناف لتبدأ متابعة المخزون.')}</div></div>`}
function purchasesPage(){let rows=db.purchases.slice().reverse().map(p=>`<tr><td class="primary-cell">${esc(p.code)}</td><td>${esc(p.supplier||'—')}</td><td>${esc(p.item||'—')}</td><td>${esc(p.qty)}</td><td>${money(p.total)}</td><td>${esc(p.date||'—')}</td><td>${badge(p.status||'مستلم')}</td></tr>`).join('');return head('المشتريات والموردون','تسجيل مشتريات المواد الخام وتتبع الموردين',btn('＋ تسجيل شراء',"openForm('purchase')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم الشراء','المورد','الصنف','الكمية','الإجمالي','التاريخ','الحالة'],rows):empty('لا توجد عمليات شراء مسجلة.')}</div></div>`}
function installationsPage(){let rows=db.installations.slice().reverse().map(i=>`<tr><td class="primary-cell">${esc(i.code)}</td><td>${esc(projectName(i.projectId))}</td><td>${esc(i.location||'—')}</td><td>${esc(i.team||'—')}</td><td>${esc(i.date||'—')}</td><td>${badge(i.status||'مجدول')}</td><td>${btn('تحديث',`editItem('installation','${i.id}')`,'btn-light btn-small')}</td></tr>`).join('');return head('التركيب والتسليم','جدولة فرق التركيب وتوثيق إنجاز المشاريع في الموقع',btn('＋ موعد تركيب',"openForm('installation')"))+`<div class="panel"><div class="panel-body">${rows?table(['رقم العملية','المشروع','الموقع','الفريق','التاريخ','الحالة','الإجراءات'],rows):empty('لا توجد عمليات تركيب مجدولة.')}</div></div>`}
function invoicesPage(){
 const invoices=db.invoices.slice().reverse();
 const paidTotal=invoices.reduce((sum,i)=>sum+(Number(i.paid)||0),0);
 const invoiceTotal=invoices.reduce((sum,i)=>sum+(Number(i.total)||0),0);
 const outstanding=Math.max(0,invoiceTotal-paidTotal);
 const invoiceStatus=i=>(+i.paid||0)>=(+i.total||0)?'مسدد':(+i.paid||0)>0?'مدفوع جزئيًا':'غير مسدد';
 const rows=invoices.map(i=>{
  const status=invoiceStatus(i);
  const due=Math.max(0,(+i.total||0)-(+i.paid||0));
  const searchText=[i.code,customerName(i.customerId),i.date,status].join(' ').toLowerCase();
  return `<tr class="invoice-row" data-status="${esc(status)}" data-search="${esc(searchText)}"><td><span class="primary-cell invoice-code">${esc(i.code||'—')}</span><span class="sub-cell">${esc(i.date||'—')}</span></td><td><span class="primary-cell">${esc(customerName(i.customerId))}</span></td><td class="invoice-amount">${money(i.total)}</td><td>${money(i.paid)}</td><td class="invoice-due ${due>0?'is-due':''}">${money(due)}</td><td>${badge(status)}</td><td><div class="invoice-row-actions">${btn('تعديل',`openForm('invoice','${i.id}')`,'btn-light btn-small')} ${btn('طباعة / PDF',`printInvoice('${i.id}')`,'btn-light btn-small')} <button class="quote-delete" title="حذف الفاتورة" aria-label="حذف الفاتورة" onclick="deleteItem('invoices','${i.id}')">حذف</button></div></td></tr>`;
 }).join('');
 return `<section class="document-management-page invoices-management">`+head('الفواتير والدفعات','تابع الفواتير والتحصيلات والمبالغ المستحقة من لوحة واحدة.',btn('＋ فاتورة جديدة',"openForm('invoice')"))+
 `<div class="document-kpi-grid invoice-summary-grid">
  <article class="invoice-kpi-card"><span class="invoice-kpi-icon">▤</span><div><small>عدد الفواتير</small><strong>${invoices.length}</strong><em>إجمالي الفواتير المسجلة</em></div></article>
  <article class="invoice-kpi-card"><span class="invoice-kpi-icon">ر.ق</span><div><small>إجمالي الفواتير</small><strong>${money(invoiceTotal)}</strong><em>القيمة الإجمالية</em></div></article>
  <article class="invoice-kpi-card is-paid"><span class="invoice-kpi-icon">✓</span><div><small>إجمالي المقبوضات</small><strong>${money(paidTotal)}</strong><em>المبالغ المحصلة</em></div></article>
  <article class="invoice-kpi-card is-due"><span class="invoice-kpi-icon">◷</span><div><small>المبالغ المتبقية</small><strong>${money(outstanding)}</strong><em>الرصيد غير المحصل</em></div></article>
 </div>
 <div class="panel invoice-list-panel document-list-panel"><div class="panel-head"><div><h3>سجل الفواتير</h3><p>راجع حالة السداد، وابحث عن فاتورة، أو سجّل دفعة جديدة.</p></div><span class="document-count-pill">${invoices.length} فاتورة</span></div><div class="panel-body">
 <div class="document-toolbar invoice-toolbar"><div class="invoice-search-wrap"><span>⌕</span><input id="invoiceSearch" class="field" placeholder="ابحث برقم الفاتورة أو اسم العميل" oninput="filterInvoiceRows()" aria-label="البحث في الفواتير"></div><select id="invoiceStatusFilter" class="field" onchange="filterInvoiceRows()" aria-label="تصفية حالة السداد"><option value="">كل الحالات</option><option>مسدد</option><option>مدفوع جزئيًا</option><option>غير مسدد</option></select><span class="document-result-count" id="invoiceResultCount">${invoices.length} فاتورة</span></div>
 ${rows?`<div class="table-wrap invoice-table-wrap"><table class="document-list-table invoice-list-table"><thead><tr><th>رقم الفاتورة / التاريخ</th><th>العميل</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>حالة السداد</th><th>الإجراءات</th></tr></thead><tbody id="invoiceRows">${rows}</tbody></table></div><div class="empty-state invoice-no-results" id="invoiceNoResults" hidden>لا توجد فواتير مطابقة للبحث أو التصفية.</div>`:empty('لا توجد فواتير مسجلة. يمكنك إنشاء فاتورة جديدة للبدء.')}
 </div></div></section>`;
}
function filterInvoiceRows(){const search=(document.getElementById('invoiceSearch')?.value||'').trim().toLowerCase(),status=document.getElementById('invoiceStatusFilter')?.value||'';const rows=[...document.querySelectorAll('.invoice-row')];let shown=0;rows.forEach(row=>{const match=(!search||(row.dataset.search||'').includes(search))&&(!status||row.dataset.status===status);row.hidden=!match;if(match)shown++});const count=document.getElementById('invoiceResultCount');if(count)count.textContent=`${shown} فاتورة`;const empty=document.getElementById('invoiceNoResults');if(empty)empty.hidden=shown!==0||rows.length===0}
function expensesPage(){let rows=db.expenses.slice().reverse().map(e=>`<tr><td class="primary-cell">${esc(e.title)}</td><td>${esc(e.category||'عام')}</td><td>${money(e.amount)}</td><td>${esc(e.date||'—')}</td><td>${esc(e.note||'—')}</td><td>${btn('حذف',`deleteItem('expenses','${e.id}')`,'btn-danger btn-small')}</td></tr>`).join('');return head('المصروفات','تسجيل النفقات التشغيلية ومتابعة تكاليف الورشة',btn('＋ مصروف جديد',"openForm('expense')"))+`<div class="stats-grid">${stat('إجمالي المصروفات',money(db.expenses.reduce((s,e)=>s+(+e.amount||0),0)),'↗')}${stat('عدد القيود',db.expenses.length,'▤')}</div><div class="panel"><div class="panel-body">${rows?table(['المصروف','التصنيف','المبلغ','التاريخ','ملاحظات','الإجراءات'],rows):empty('لا توجد مصروفات مسجلة.')}</div></div>`}
function reportsPage(){let sales=db.invoices.reduce((s,x)=>s+(+x.total||0),0),paid=db.invoices.reduce((s,x)=>s+(+x.paid||0),0),cost=db.projects.reduce((s,x)=>s+(+x.cost||0),0),expenses=db.expenses.reduce((s,x)=>s+(+x.amount||0),0);return head('التقارير','ملخصات تشغيلية ومالية من البيانات المحفوظة',btn('طباعة التقرير','window.print()','btn-light'))+`<div class="stats-grid">${stat('إجمالي الفواتير',money(sales),'▣')}${stat('إجمالي المقبوضات',money(paid),'↗')}${stat('تكاليف المشاريع المسجلة',money(cost),'⚒')}${stat('المصروفات',money(expenses),'↘')}</div><div class="two-col"><div class="panel"><div class="panel-head"><h3>ملخص المشاريع</h3></div>${table(['المؤشر','القيمة'],`<tr><td>إجمالي المشاريع</td><td>${db.projects.length}</td></tr><tr><td>المشاريع المكتملة</td><td>${db.projects.filter(x=>x.status==='مكتمل').length}</td></tr><tr><td>أوامر التصنيع</td><td>${db.production.length}</td></tr><tr><td>عمليات التركيب</td><td>${db.installations.length}</td></tr>`)}</div><div class="panel"><div class="panel-head"><h3>ملخص مالي</h3></div>${table(['المؤشر','القيمة'],`<tr><td>المبالغ المستحقة</td><td>${money(Math.max(0,sales-paid))}</td></tr><tr><td>تكلفة المخزون الحالية</td><td>${money(db.inventory.reduce((s,x)=>s+(+x.qty||0)*(+x.cost||0),0))}</td></tr><tr><td>المصروفات المسجلة</td><td>${money(expenses)}</td></tr><tr><td>صافي تقديري قبل تسويات أخرى</td><td>${money(paid-expenses-cost)}</td></tr>`)}</div></div><div class="notice">التقارير تعتمد على البيانات التي أدخلتها. صافي الربح هنا تقديري، ولا يُعد قوائم مالية معتمدة.</div>`}
function settingsPage(){const lowStock=db.inventory.filter(x=>Number(x.min)>0&&Number(x.qty||0)<=Number(x.min)).length;return head('الإعدادات والنسخ الاحتياطي','تحكم في بيانات الورشة والمظهر وحماية بياناتك')+`<div class="settings-card language-card"><h3>لغة النظام / Interface Language</h3><p>اختر لغة واجهة البرنامج. سيتم حفظ اختيارك على هذا الجهاز. / Choose the application language. Your preference is saved on this device.</p><label for="appLanguage">اللغة / Language</label><select id="appLanguage" class="field" onchange="setLanguage(this.value)"><option value="ar" ${!isEnglish()?'selected':''}>العربية</option><option value="en" ${isEnglish()?'selected':''}>English</option></select></div><div class="settings-section-title"><span>🏢</span><div><h2>بيانات الورشة والمستندات</h2><p>تُحفظ التفضيلات هنا دون تغيير تصميم قوالب PDF الحالية.</p></div></div><div class="settings-card"><form id="settingsForm" onsubmit="saveSettings(event)"><div class="form-grid"><div class="full"><label>اسم الورشة</label><input class="field" name="shopName" value="${esc(db.settings.shopName)}" required></div><div><label>رقم الهاتف</label><input class="field" name="phone" value="${esc(db.settings.phone)}"></div><div><label>العملة</label><select class="field" name="currency"><option value="ر.ق" ${db.settings.currency==='ر.ق'?'selected':''}>ريال قطري (ر.ق)</option><option value="ر.س" ${db.settings.currency==='ر.س'?'selected':''}>ريال سعودي (ر.س)</option><option value="د.إ" ${db.settings.currency==='د.إ'?'selected':''}>درهم إماراتي (د.إ)</option><option value="د.ك" ${db.settings.currency==='د.ك'?'selected':''}>دينار كويتي (د.ك)</option><option value="د.ب" ${db.settings.currency==='د.ب'?'selected':''}>دينار بحريني (د.ب)</option><option value="ع.ر" ${db.settings.currency==='ع.ر'?'selected':''}>ريال عماني (ع.ر)</option><option value="ج.م" ${db.settings.currency==='ج.م'?'selected':''}>جنيه مصري (ج.م)</option><option value="د.أ" ${db.settings.currency==='د.أ'?'selected':''}>دينار أردني (د.أ)</option><option value="USD" ${db.settings.currency==='USD'?'selected':''}>دولار أمريكي (USD)</option><option value="EUR" ${db.settings.currency==='EUR'?'selected':''}>يورو (EUR)</option></select></div><div class="full"><label>العنوان</label><input class="field" name="address" value="${esc(db.settings.address)}"></div><div><label>الضريبة %</label><input class="field" type="number" min="0" max="100" step=".01" name="tax" value="${esc(db.settings.tax)}"></div></div><div class="form-actions"><button class="btn btn-primary">حفظ بيانات الورشة</button></div></form></div><div class="settings-section-title"><span>🎨</span><div><h2>المظهر والتفضيلات</h2><p>خصص واجهة التطبيق لتناسب طريقة استخدامك.</p></div></div><div class="settings-card"><div class="form-grid"><div><label for="appTheme">مظهر النظام</label><select id="appTheme" class="field"><option value="light" ${db.settings.theme!=='dark'?'selected':''}>فاتح</option><option value="dark" ${db.settings.theme==='dark'?'selected':''}>داكن</option></select></div><div><label for="fontScale">حجم الخط</label><select id="fontScale" class="field"><option value="90" ${Number(db.settings.fontScale)===90?'selected':''}>صغير</option><option value="100" ${!db.settings.fontScale||Number(db.settings.fontScale)===100?'selected':''}>متوسط</option><option value="110" ${Number(db.settings.fontScale)===110?'selected':''}>كبير</option><option value="115" ${Number(db.settings.fontScale)===115?'selected':''}>كبير جدًا</option></select></div><div><label for="backupReminderDays">تذكير النسخ الاحتياطي (يوم)</label><select id="backupReminderDays" class="field"><option value="1" ${Number(db.settings.backupReminderDays)===1?'selected':''}>كل يوم</option><option value="7" ${!db.settings.backupReminderDays||Number(db.settings.backupReminderDays)===7?'selected':''}>كل 7 أيام</option><option value="14" ${Number(db.settings.backupReminderDays)===14?'selected':''}>كل 14 يومًا</option><option value="30" ${Number(db.settings.backupReminderDays)===30?'selected':''}>كل 30 يومًا</option></select></div></div><div class="form-actions"><button class="btn btn-primary" onclick="savePreferences()" type="button">حفظ التفضيلات</button></div></div><div class="settings-section-title"><span>▤</span><div><h2>طريقة عرض القوائم والأقسام</h2><p>اختر العرض المناسب وأخفِ الأقسام التي لا تستخدمها.</p></div></div><div class="settings-card"><div class="form-grid"><div><label for="listViewMode">طريقة عرض القوائم</label><select id="listViewMode" class="field"><option value="table" ${db.settings.listView!=='cards'?'selected':''}>جدول</option><option value="cards" ${db.settings.listView==='cards'?'selected':''}>بطاقات</option></select></div><div class="full"><label>إظهار أو إخفاء الأقسام غير المستخدمة</label><div class="section-toggle-grid">${[['customers','العملاء'],['projects','المشاريع والقياسات'],['quotes','عروض الأسعار'],['production','أوامر التصنيع'],['inventory','المخزون والمواد'],['purchases','المشتريات والموردون'],['installations','التركيب والتسليم'],['invoices','الفواتير والدفعات'],['expenses','المصروفات'],['reports','التقارير']].map(([k,v])=>`<label class="section-toggle"><input type="checkbox" name="visibleSection" value="${k}" ${!(db.settings.hiddenSections||[]).includes(k)?'checked':''}> ${v}</label>`).join('')}</div><p class="settings-hint">لوحة التحكم والإعدادات تبقيان ظاهرتين دائمًا حتى لا تفقد الوصول إلى النظام.</p></div></div><div class="form-actions"><button class="btn btn-primary" type="button" onclick="saveSystemManagement()">حفظ طريقة العرض والأقسام</button></div></div><div class="settings-section-title"><span>🔐</span><div><h2>الأمان والحماية</h2><p>الحماية اختيارية، ويمكن تشغيلها أو إيقافها في أي وقت.</p></div></div><div class="settings-card"><h3>رمز PIN وقفل التطبيق</h3><p>${db.settings.pinEnabled?'الحماية مفعّلة على هذا الجهاز.':'الحماية غير مفعّلة. يمكنك إضافة رمز PIN من 4 إلى 8 أرقام.'}</p><div class="form-grid"><div><label for="autoLockMinutes">القفل التلقائي بعد عدم الاستخدام</label><select id="autoLockMinutes" class="field"><option value="1" ${Number(db.settings.autoLockMinutes)===1?'selected':''}>دقيقة واحدة</option><option value="5" ${Number(db.settings.autoLockMinutes||5)===5?'selected':''}>5 دقائق</option><option value="10" ${Number(db.settings.autoLockMinutes)===10?'selected':''}>10 دقائق</option><option value="15" ${Number(db.settings.autoLockMinutes)===15?'selected':''}>15 دقيقة</option><option value="30" ${Number(db.settings.autoLockMinutes)===30?'selected':''}>30 دقيقة</option></select></div><div><label>حالة الحماية</label><div class="settings-backup-status">${db.settings.pinEnabled?'مفعّلة':'متوقفة'}</div></div></div><div class="form-actions"><button class="btn btn-primary" type="button" onclick="${db.settings.pinEnabled?'changePin()':'enablePin()'}">${db.settings.pinEnabled?'تغيير رمز PIN':'تفعيل رمز PIN'}</button>${db.settings.pinEnabled?'<button class="btn btn-light" type="button" onclick="disablePin()">إيقاف الحماية</button><button class="btn btn-light" type="button" onclick="lockApp()">قفل التطبيق الآن</button>':''}<button class="btn btn-light" type="button" onclick="saveAutoLock()">حفظ مدة القفل</button></div><p class="settings-hint">ملاحظة: رمز PIN يمنع فتح واجهة التطبيق دون الرمز، لكنه لا يشفر قاعدة البيانات المخزنة في المتصفح. استخدم نسخة احتياطية محفوظة في مكان آمن.</p></div><div class="settings-section-title"><span>⚙</span><div><h2>إدارة النظام</h2><p>حالة البيانات وإجراءات الصيانة الأساسية.</p></div></div><div class="settings-card"><div class="settings-metrics">${dataOverview()}</div><div class="settings-backup-status">حجم قاعدة البيانات التقريبي: ${Math.max(1,Math.round(new Blob([JSON.stringify(db)]).size/1024))} كيلوبايت</div><div class="settings-export-actions"><button class="btn btn-light" type="button" onclick="render()">تحديث حالة النظام</button><button class="btn btn-danger" type="button" onclick="resetData()">إعادة ضبط جميع البيانات</button></div></div><div class="settings-section-title"><span>💾</span><div><h2>النسخ الاحتياطي والاستعادة</h2><p>احتفظ بنسخة خارج الجهاز لاستعادة بياناتك عند الحاجة.</p></div></div><div class="two-col"><div class="settings-card"><h3>النسخ الاحتياطي</h3><p>تنزيل نسخة JSON كاملة تشمل بيانات الورشة وإعداداتها.</p><div class="settings-backup-status">${backupStatusText()}</div><button class="btn btn-primary" onclick="exportBackup()">⬇ تنزيل نسخة احتياطية</button><p class="settings-hint">التذكير مضبوط على كل ${Number(db.settings.backupReminderDays)||7} أيام. التنزيل يتطلب الضغط على الزر.</p></div><div class="settings-card"><h3>استعادة نسخة احتياطية</h3><p>ستُستبدل البيانات الحالية بمحتويات النسخة المختارة.</p><input class="field" type="file" id="backupFile" accept=".json,application/json"><div class="form-actions"><button class="btn btn-light" onclick="importBackup()">استعادة البيانات</button></div></div></div><div class="settings-section-title"><span>📊</span><div><h2>إدارة وتصدير البيانات</h2><p>ملخص سريع للسجلات وتصديرها بصيغ قابلة للفتح في برامج الجداول.</p></div></div><div class="settings-card"><div class="settings-metrics">${dataOverview()}</div><div class="settings-warning ${lowStock?'is-warning':''}">${lowStock?`تنبيه: يوجد ${lowStock} صنفًا وصل إلى حد التنبيه أو أقل.`:'لا توجد أصناف مخزون وصلت إلى حد التنبيه.'}</div><div class="settings-export-actions"><button class="btn btn-primary" onclick="exportAllCSV()">تصدير الجداول الأساسية CSV</button><button class="btn btn-light" onclick="exportCSV('customers')">العملاء CSV</button><button class="btn btn-light" onclick="exportCSV('invoices')">الفواتير CSV</button><button class="btn btn-light" onclick="exportCSV('quotes')">عروض الأسعار CSV</button><button class="btn btn-light" onclick="exportCSV('inventory')">المخزون CSV</button><button class="btn btn-light" onclick="exportCSV('expenses')">المصروفات CSV</button></div></div>`}
function saveSystemManagement(){db.settings.listView=document.getElementById('listViewMode')?.value==='cards'?'cards':'table';db.settings.hiddenSections=[...document.querySelectorAll('input[name="visibleSection"]:not(:checked)')].map(x=>x.value);saveDB();applyListView();applyNavVisibility();toast('تم حفظ طريقة العرض والأقسام');}
function saveAutoLock(){db.settings.autoLockMinutes=Math.max(1,Number(document.getElementById('autoLockMinutes')?.value)||5);saveDB();resetInactivityTimer();toast('تم حفظ مدة القفل التلقائي');}
function applyNavVisibility(){document.querySelectorAll('.nav-item').forEach(b=>{const p=b.dataset.page,hide=(db.settings.hiddenSections||[]).includes(p)&&!['dashboard','settings'].includes(p);b.style.display=hide?'none':'';});if((db.settings.hiddenSections||[]).includes(currentPage)&&!['dashboard','settings'].includes(currentPage))setPage('dashboard');}
function applyListView(){document.body.classList.toggle('list-cards',db.settings.listView==='cards');labelTableCells();}
function labelTableCells(){document.querySelectorAll('#content table').forEach(t=>{const labels=[...t.querySelectorAll('thead th')].map(x=>x.textContent.trim());t.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>{if(td.tagName==='TD'&&labels[i])td.dataset.label=labels[i]}));});}
async function pinDigest(pin,salt){if(!window.crypto?.subtle||!window.TextEncoder){throw new Error('SECURE_CRYPTO_UNAVAILABLE')}const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},material,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function enablePin(){const pin=prompt('أدخل رمز PIN من 4 إلى 8 أرقام');if(pin===null)return;if(!/^\d{4,8}$/.test(pin)){toast('يجب أن يتكون الرمز من 4 إلى 8 أرقام');return}const again=prompt('أعد إدخال رمز PIN للتأكيد');if(pin!==again){toast('الرمزان غير متطابقين');return}try{const salt=uid('SALT')+uid('');db.settings.pinSalt=salt;db.settings.pinHash=await pinDigest(pin,salt);db.settings.pinEnabled=true;saveDB();render();lockApp();}catch(e){toast('تعذر تفعيل PIN: المتصفح لا يدعم التخزين الآمن للرمز');}}
async function changePin(){const old=prompt('أدخل رمز PIN الحالي');if(old===null)return;try{if(await pinDigest(old,db.settings.pinSalt)!==db.settings.pinHash){toast('رمز PIN الحالي غير صحيح');return}const pin=prompt('أدخل رمز PIN الجديد من 4 إلى 8 أرقام');if(pin===null)return;if(!/^\d{4,8}$/.test(pin)){toast('يجب أن يتكون الرمز من 4 إلى 8 أرقام');return}if(prompt('أعد إدخال رمز PIN الجديد للتأكيد')!==pin){toast('الرمزان غير متطابقين');return}const salt=uid('SALT')+uid('');db.settings.pinSalt=salt;db.settings.pinHash=await pinDigest(pin,salt);db.settings.pinEnabled=true;saveDB();render();toast('تم تغيير رمز PIN بنجاح')}catch(e){toast('تعذر التحقق من رمز PIN');}}
async function disablePin(){const pin=prompt('أدخل رمز PIN الحالي لإيقاف الحماية');if(pin===null)return;try{if(await pinDigest(pin,db.settings.pinSalt)!==db.settings.pinHash){toast('رمز PIN غير صحيح');return}db.settings.pinEnabled=false;db.settings.pinHash='';db.settings.pinSalt='';saveDB();document.getElementById('pinLockOverlay')?.remove();render();toast('تم إيقاف الحماية');}catch(e){toast('تعذر التحقق من رمز PIN');}}
function lockApp(){if(!db.settings.pinEnabled)return;clearTimeout(window.__pinIdleTimer);let ov=document.getElementById('pinLockOverlay');if(!ov){ov=document.createElement('div');ov.id='pinLockOverlay';ov.className='pin-lock-overlay';ov.innerHTML='<div class="pin-lock-card"><div class="pin-lock-icon">🔒</div><h2>التطبيق مقفل</h2><p>أدخل رمز PIN للمتابعة</p><input id="pinUnlockInput" class="field" type="password" inputmode="numeric" maxlength="8" placeholder="رمز PIN" autocomplete="off"><button class="btn btn-primary" id="pinUnlockButton" type="button">فتح التطبيق</button><small id="pinUnlockError"></small></div>';document.body.appendChild(ov);document.getElementById('pinUnlockButton').onclick=unlockApp;document.getElementById('pinUnlockInput').addEventListener('keydown',e=>{if(e.key==='Enter')unlockApp()});}ov.style.display='flex';document.getElementById('pinUnlockInput').value='';document.getElementById('pinUnlockError').textContent='';document.getElementById('pinUnlockInput').focus();}
async function unlockApp(){const input=document.getElementById('pinUnlockInput'),err=document.getElementById('pinUnlockError'),pin=input?.value||'';try{if(await pinDigest(pin,db.settings.pinSalt)===db.settings.pinHash){document.getElementById('pinLockOverlay')?.remove();resetInactivityTimer();return}err.textContent='رمز PIN غير صحيح';input.value='';input.focus();}catch(e){err.textContent='تعذر التحقق من الرمز على هذا الجهاز';}}
function resetInactivityTimer(){clearTimeout(window.__pinIdleTimer);if(!db.settings.pinEnabled)return;const mins=Math.max(1,Number(db.settings.autoLockMinutes)||5);window.__pinIdleTimer=setTimeout(lockApp,mins*60000);}
function initSecurity(){if(db.settings.pinEnabled)lockApp();['pointerdown','keydown','touchstart','scroll'].forEach(ev=>document.addEventListener(ev,()=>{if(!document.getElementById('pinLockOverlay'))resetInactivityTimer();},{passive:true}));applyNavVisibility();applyListView();const target=document.getElementById('content');if(target&&window.MutationObserver)new MutationObserver(()=>labelTableCells()).observe(target,{childList:true,subtree:true});resetInactivityTimer();}
function options(items,selected){return `<option value="">اختر...</option>`+items.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name||x.code||x.title)}</option>`).join('')}
const schemas={
 customer:{title:'إضافة عميل',collection:'customers',prefix:'CUS',fields:[['name','اسم العميل','text',1],['phone','رقم الهاتف','tel'],['type','نوع العميل','select',['فرد','شركة','مقاول']],['address','العنوان / موقع العمل','text'],['note','ملاحظات','textarea']]},
 project:{title:'مشروع جديد',collection:'projects',prefix:'PRJ',fields:[['name','اسم المشروع','text',1],['customerId','العميل','selectCustomers',1],['type','نوع العمل','select',['باب ألمنيوم','شبابيك ألمنيوم','واجهة زجاجية','مطبخ ألمنيوم','بوابة حديد','درابزين','مظلة','هيكل معدني','أعمال أخرى']],['width','العرض','number'],['height','الارتفاع','number'],['unit','وحدة القياس','select',['سم','مم','متر']],['qty','العدد','number',1],['unitPrice','سعر الوحدة','number'],['total','قيمة البيع','number'],['cost','التكلفة التقديرية','number'],['status','الحالة','select',['جديد','بانتظار القياسات','بانتظار موافقة العميل','قيد التصنيع','جاهز للتركيب','مكتمل']],['due','موعد التسليم','date'],['note','ملاحظات / مواصفات','textarea']]},
 quote:{title:'إنشاء عرض سعر',collection:'quotes',prefix:'QT',fields:[['customerEntry','اختر اسم العميل','customerEntry'],['date','تاريخ عرض السعر','date',1],['code','رقم العرض','text',1],['extra','تكاليف إضافية','number'],['discount','الخصم','number'],['status','الحالة','select',['مسودة','مرسل للعميل','معتمد','مرفوض']],['note','المواصفات والشروط','textarea']]},
 production:{title:'إنشاء أمر تصنيع',collection:'production',prefix:'FAB',fields:[['projectId','المشروع','selectProjects',1],['stage','مرحلة العمل','select',['تجهيز المواد','القص','التشغيل والتخريم','التجميع','اللحام','التشطيب والدهان','تركيب الزجاج والإكسسوارات','الفحص النهائي']],['worker','الفني / المسؤول','text'],['due','موعد التسليم','date'],['status','الحالة','select',['جديد','جاهز للتصنيع','قيد التصنيع','قيد التشطيب','تحت الفحص','جاهز للتركيب','مكتمل','ملغي']],['note','ملاحظات التصنيع','textarea']]},
 inventory:{title:'إضافة مادة للمخزون',collection:'inventory',prefix:'STK',fields:[['name','اسم المادة / الصنف','text',1],['category','الفئة','select',['قطاع ألمنيوم','حديد','زجاج','إكسسوارات','مواد لحام','دهان وتشطيب','أدوات','أخرى']],['unit','الوحدة','select',['عود','متر','متر مربع','قطعة','كيلوغرام','علبة','لتر']],['qty','الكمية الحالية','number',1],['min','حد التنبيه','number'],['cost','تكلفة الوحدة','number'],['code','كود الصنف','text'],['note','موقع التخزين / ملاحظات','textarea']]},
 purchase:{title:'تسجيل عملية شراء',collection:'purchases',prefix:'PUR',fields:[['supplier','اسم المورد','text',1],['item','الصنف المشترى','text',1],['qty','الكمية','number',1],['unitCost','تكلفة الوحدة','number',1],['date','تاريخ الشراء','date'],['status','الحالة','select',['طلب شراء','مستلم','مرتجع']],['note','ملاحظات / رقم الفاتورة','textarea']]},
 installation:{title:'جدولة عملية تركيب',collection:'installations',prefix:'INS',fields:[['projectId','المشروع','selectProjects',1],['location','الموقع','text',1],['team','فريق التركيب','text'],['date','تاريخ التركيب','date',1],['status','الحالة','select',['مجدول','قيد التنفيذ','مكتمل','مؤجل']],['note','ملاحظات','textarea']]},
 invoice:{title:'إنشاء فاتورة',collection:'invoices',prefix:'INV',fields:[['customerEntry','اختر اسم العميل','customerEntry'],['date','تاريخ الفاتورة','date',1],['code','رقم الفاتورة','text',1],['paid','المبلغ المدفوع','number'],['extra','تكاليف إضافية','number'],['discount','الخصم','number'],['note','المواصفات والشروط','textarea']]},
 expense:{title:'تسجيل مصروف',collection:'expenses',prefix:'EXP',fields:[['title','اسم المصروف','text',1],['category','التصنيف','select',['مواد','رواتب','إيجار','نقل','كهرباء ومياه','صيانة معدات','أدوات','إداري','أخرى']],['amount','المبلغ','number',1],['date','التاريخ','date',1],['note','ملاحظات / مرجع','textarea']]}
};
function quoteWorkRow(i,old={},isInvoice=false){const titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;return `<div class="quote-work-row full" data-work-row="${i}"><div class="quote-work-title"><label for="${titleKey}">وصف العمل ${i}</label><textarea class="field quote-description-input" id="${titleKey}" name="${titleKey}" rows="1" oninput="this.style.height='auto';this.style.height=this.scrollHeight+'px'" ${i===1?'required':''} placeholder="اكتب وصف العمل">${esc(old[titleKey]||'')}</textarea></div><div><label for="${qtyKey}">العدد</label><input class="field quote-number-input" id="${qtyKey}" name="${qtyKey}" type="number" inputmode="decimal" step="0.01" min="0" autocomplete="off" value="${esc(old[qtyKey]??(isInvoice?'':(i===1?1:'')))}" ${!isInvoice&&i===1?'required':''}></div><div><label for="${priceKey}">السعر</label><input class="field quote-number-input" id="${priceKey}" name="${priceKey}" type="number" inputmode="decimal" step="0.01" min="0" autocomplete="off" value="${esc(old[priceKey]??(i===1?0:''))}" ${i===1?'required':''}></div></div>`}
function addQuoteWorkRow(type='quote'){const wrap=document.getElementById('quoteWorkRows');if(!wrap)return;const next=Math.max(0,...[...wrap.querySelectorAll('[data-work-row]')].map(x=>Number(x.dataset.workRow)||0))+1;wrap.insertAdjacentHTML('beforeend',quoteWorkRow(next,{},type==='invoice'));}
function openForm(type,id=null){let sc=schemas[type];if(!sc)return;let old=id?db[sc.collection].find(x=>x.id===id):null;let fields=sc.fields.map(f=>{let [name,label,kind,extra]=f;let value=old?.[name]??(name==='customerEntry'&&(type==='quote'||type==='invoice')?(db.customers.find(c=>c.id===old?.customerId)?.name||old?.customerName||''):name==='date'?dateNow():name==='code'&&type==='quote'?nextQuoteCode():name==='code'&&type==='invoice'?uid('INV'):name==='customerName'&&type==='quote'?'':name==='qty'?1:name==='unit'?'سم':name==='status'?(type==='project'?'جديد':type==='quote'?'مسودة':type==='production'?'جديد':type==='installation'?'مجدول':''):name==='paid'?0:'');let req=extra===1;let input='';if(kind==='customerEntry')input=`<input class="field" name="customerEntry" type="text" list="quoteCustomerNames" value="${esc(value)}" placeholder="اختر اسماً مسجلاً أو اكتب اسم عميل جديد" autocomplete="off"><datalist id="quoteCustomerNames">${db.customers.map(c=>`<option value="${esc(c.name||'')}"></option>`).join('')}</datalist>`;else if(kind==='selectCustomers')input=`<select class="field" name="${name}" ${req?'required':''}>${options(db.customers,value)}</select>`;else if(kind==='selectProjects')input=`<select class="field" name="${name}" ${req?'required':''}>${options(db.projects,value)}</select>`;else if(kind==='select')input=`<select class="field" name="${name}" ${req?'required':''}>${extra.map(s=>`<option ${s===value?'selected':''}>${s}</option>`).join('')}</select>`;else if(kind==='textarea')input=`<textarea class="field" rows="3" name="${name}">${esc(value)}</textarea>`;else input=`<input class="field" name="${name}" type="${kind}" value="${esc(value)}" ${req?'required':''} ${kind==='number'?'step="0.01" min="0"':''}>`;return `<div class="${kind==='textarea'?'full':''}"><label>${label}</label>${input}</div>`}).join('');if(type==='quote'||type==='invoice'){let count=1;for(let i=2;i<100;i++){if(old?.[`title${i}`]||old?.[`qty${i}`]||old?.[`unitPrice${i}`])count=i;}const rows=Array.from({length:count},(_,j)=>quoteWorkRow(j+1,old||{},type==='invoice')).join('');const workBlock=`<div class="full quote-work-section"><div id="quoteWorkRows">${rows}</div><button class="btn btn-light quote-add-btn" type="button" onclick="addQuoteWorkRow('${type}')">＋ إضافة وصف عمل</button></div>`;const firstEnd=fields.indexOf('</div>')+6;fields=fields.slice(0,firstEnd)+workBlock+fields.slice(firstEnd);}document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>${old?'تعديل':'إضافة'} ${sc.title.replace(/^(إضافة|إنشاء|تسجيل|جدولة) /,'')}</h2><button class="modal-close" onclick="closeModal()">×</button></div><form id="dataForm" onsubmit="saveForm(event,'${type}','${id||''}')"><div class="modal-body"><div class="form-grid">${fields}</div><p style="font-size:10px;color:#9aa6b1;margin:16px 0 0">* الحقول المطلوبة يجب تعبئتها قبل الحفظ.</p></div><div class="modal-footer"><button class="btn btn-primary" type="submit">حفظ البيانات</button><button class="btn btn-light" type="button" onclick="closeModal()">إلغاء</button></div></form>`;document.getElementById('modalBackdrop').classList.add('show');applyLocale();document.querySelectorAll('.quote-description-input').forEach(el=>{el.style.height='auto';el.style.height=el.scrollHeight+'px'})}
function closeModal(){document.getElementById('modalBackdrop').classList.remove('show')}
function parseNumeric(v){if(v===undefined||v===null)return 0;let s=String(v).trim().replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٬,]/g,'').replace(/٫/g,'.').replace(/[^0-9.\-]/g,'');const n=Number(s);return Number.isFinite(n)?n:0}
function saveForm(e,type,id){e.preventDefault();const sc=schemas[type],fd=new FormData(e.target),obj={};for(const [k,v] of fd.entries())obj[k]=v.trim();for(const f of sc.fields){let k=f[0];if(f[2]==='number')obj[k]=parseNumeric(obj[k])}if(type==='project'){if(!obj.total&&obj.width&&obj.height)obj.total=(Number(obj.width)/100)*(Number(obj.height)/100)*Number(obj.qty||1)*Number(obj.unitPrice||0);if(!obj.total)obj.total=Number(obj.qty||1)*Number(obj.unitPrice||0)}if(type==='quote'){let subtotal=0;for(const k of Object.keys(obj)){const m=k.match(/^(?:qty|unitPrice)(\d*)$/);if(m){obj[k]=parseNumeric(obj[k])}}for(let i=1;i<100;i++){const titleKey=i===1?'title':`title${i}`,qtyKey=i===1?'qty':`qty${i}`,priceKey=i===1?'unitPrice':`unitPrice${i}`;if(obj[titleKey]!==undefined||obj[qtyKey]!==undefined||obj[priceKey]!==undefined)subtotal+=parseNumeric(obj[qtyKey])*parseNumeric(obj[priceKey])}obj.total=Math.max(0,subtotal+parseNumeric(obj.extra)-parseNumeric(obj.discount));const oldQuote=id?db.quotes.find(x=>x.id===id):null;obj.code=(obj.code||oldQuote?.code||nextQuoteCode()).trim();if(db.quotes.some(x=>x.id!==id&&String(x.code||'').toLowerCase()===obj.code.toLowerCase())){toast('رقم العرض مستخدم بالفعل، اختر رقماً آخر');return}obj.date=obj.date||oldQuote?.date||dateNow();const enteredCustomer=(obj.customerEntry||'').trim();delete obj.customerEntry;if(enteredCustomer){let customer=db.customers.find(c=>String(c.name||'').trim().toLowerCase()===enteredCustomer.toLowerCase());if(!customer){customer={id:uid('CUS'),code:uid('CUS'),name:enteredCustomer};db.customers.push(customer)}obj.customerId=customer.id}else{obj.customerId=''}if(id&&oldQuote?.status==='معتمد')obj.status='مسودة'}if(type==='purchase'){obj.total=Number(obj.qty||0)*Number(obj.unitCost||0);let item=db.inventory.find(x=>x.name===obj.item);if(obj.status==='مستلم'&&item){item.qty=Number(item.qty||0)+Number(obj.qty||0)}}if(type==='invoice'){let subtotal=0;for(const k of Object.keys(obj)){const m=k.match(/^(?:qty|unitPrice)(\d*)$/);if(m)obj[k]=parseNumeric(obj[k])}for(let i=1;i<100;i++){const qk=i===1?'qty':`qty${i}`,pk=i===1?'unitPrice':`unitPrice${i}`;if(obj[qk]!==undefined||obj[pk]!==undefined){const qtyText=String(obj[qk]??'').trim();const qty=qtyText===''||parseNumeric(qtyText)===0?1:parseNumeric(qtyText);subtotal+=qty*parseNumeric(obj[pk])}}obj.subtotal=subtotal;obj.total=Math.max(0,subtotal+parseNumeric(obj.extra)-parseNumeric(obj.discount))*(1+(Number(db.settings.tax||0)/100));obj.paid=Math.min(Number(obj.paid||0),obj.total);const oldInvoice=id?db.invoices.find(x=>x.id===id):null;obj.code=(obj.code||oldInvoice?.code||uid('INV')).trim();if(db.invoices.some(x=>x.id!==id&&String(x.code||'').toLowerCase()===obj.code.toLowerCase())){toast('رقم الفاتورة مستخدم بالفعل، اختر رقماً آخر');return}obj.date=obj.date||oldInvoice?.date||dateNow();const enteredCustomer=(obj.customerEntry||'').trim();delete obj.customerEntry;if(enteredCustomer){let customer=db.customers.find(c=>String(c.name||'').trim().toLowerCase()===enteredCustomer.toLowerCase());if(!customer){customer={id:uid('CUS'),code:uid('CUS'),name:enteredCustomer};db.customers.push(customer)}obj.customerId=customer.id}else obj.customerId=oldInvoice?.customerId||''}if(type==='customer')obj.code=id?(db.customers.find(x=>x.id===id)?.code):uid('CUS');if(type==='project')obj.code=id?(db.projects.find(x=>x.id===id)?.code):uid('PRJ');if(type==='production')obj.code=id?(db.production.find(x=>x.id===id)?.code):uid('FAB');if(type==='inventory')obj.code=obj.code||uid('STK');if(type==='installation')obj.code=id?(db.installations.find(x=>x.id===id)?.code):uid('INS');if(type==='purchase')obj.code=id?(db.purchases.find(x=>x.id===id)?.code):uid('PUR');obj.id=id||uid(type.toUpperCase());if(!obj.date&&['expense','invoice','purchase','installation'].includes(type))obj.date=dateNow();if(id){let ix=db[sc.collection].findIndex(x=>x.id===id);if(ix>=0)db[sc.collection][ix]={...db[sc.collection][ix],...obj}}else db[sc.collection].push(obj);saveDB();closeModal();render();toast('تم حفظ البيانات بنجاح')}
function editItem(type,id){if(type==='installation'){openForm(type,id);return}openForm(type,id)}
function deleteItem(collection,id){if(!confirm('هل أنت متأكد من حذف هذا السجل؟'))return;db[collection]=db[collection].filter(x=>x.id!==id);saveDB();render();toast('تم حذف السجل')}
function changeStatus(collection,id,status){const x=db[collection].find(x=>x.id===id);if(x){x.status=status;saveDB();toast('تم تحديث الحالة');render()}}
function filterRows(input,col){const table=input.closest('.panel').querySelector('tbody');if(!table)return;let q=input.value.toLowerCase();[...table.rows].forEach(r=>r.style.display=r.cells[col]?.innerText.toLowerCase().includes(q)?'':'none')}
function approveQuote(id){let q=db.quotes.find(x=>x.id===id);if(!q)return;if(q.status==='معتمد'){toast('عرض السعر معتمد بالفعل');return}if(!confirm('هل تريد اعتماد عرض السعر؟'))return;q.status='معتمد';if(!db.projects.some(p=>p.quoteId===id)){const firstTitle=q.title||'عمل حسب عرض السعر';db.projects.push({id:uid('PRJ'),code:uid('PRJ'),name:firstTitle,customerId:q.customerId,type:'عمل حسب عرض السعر',qty:q.qty||1,unitPrice:q.unitPrice||0,total:q.total,cost:0,status:'جديد',quoteId:id,due:''})}saveDB();render();toast('تم اعتماد العرض وإنشاء مشروع مرتبط')}
function cancelQuoteApproval(id){const q=db.quotes.find(x=>x.id===id);if(!q)return;if(q.status!=='معتمد'){toast('عرض السعر غير معتمد');return}if(!confirm('هل تريد إلغاء اعتماد عرض السعر؟ سيعود إلى حالة «مسودة».'))return;q.status='مسودة';const linked=db.projects.filter(p=>p.quoteId===id);linked.forEach(p=>{if(p.status==='جديد')p.status='ملغي'});saveDB();render();toast(linked.some(p=>p.status!=='ملغي')?'تم إلغاء اعتماد العرض؛ تُرك المشروع الذي بدأ العمل عليه دون تغيير.':'تم إلغاء اعتماد العرض وإلغاء المشروع المرتبط الذي لم يبدأ العمل عليه.')}
function stockMovement(id){let x=db.inventory.find(x=>x.id===id);if(!x)return;document.getElementById('modal').innerHTML=`<div class="modal-head"><h2>حركة مخزون — ${esc(x.name)}</h2><button class="modal-close" onclick="closeModal()">×</button></div><form onsubmit="applyStock(event,'${id}')"><div class="modal-body"><div class="form-grid"><div><label>نوع الحركة</label><select class="field" name="kind"><option value="in">إضافة كمية</option><option value="out">صرف كمية</option><option value="waste">هالك</option></select></div><div><label>الكمية</label><input class="field" type="number" min=".01" step=".01" name="qty" required></div><div class="full"><label>سبب الحركة</label><input class="field" name="note" placeholder="مثال: صرف لمشروع..."></div></div><p>الرصيد الحالي: <b>${esc(x.qty)}</b> ${esc(x.unit||'')}</p></div><div class="modal-footer"><button class="btn btn-primary">حفظ الحركة</button></div></form>`;document.getElementById('modalBackdrop').classList.add('show');applyLocale();document.querySelectorAll('.quote-description-input').forEach(el=>{el.style.height='auto';el.style.height=el.scrollHeight+'px'})}
function applyStock(e,id){e.preventDefault();let fd=new FormData(e.target),x=db.inventory.find(x=>x.id===id),q=Number(fd.get('qty'));if(fd.get('kind')!=='in'&&q>Number(x.qty)){toast('الكمية المصروفة أكبر من المخزون');return}x.qty=Number(x.qty)+(fd.get('kind')==='in'?q:-q);x.note=(x.note||'')+` | حركة ${fd.get('kind')} ${q}: ${fd.get('note')||''}`;saveDB();closeModal();render();toast('تم تحديث المخزون')}
function payInvoice(id){let x=db.invoices.find(x=>x.id===id);if(!x)return;let amount=prompt(`المتبقي ${money(Math.max(0,x.total-x.paid))}\nأدخل مبلغ الدفعة:`);if(amount===null)return;let n=Number(amount);if(!Number.isFinite(n)||n<=0){toast('أدخل مبلغًا صحيحًا');return}x.paid=Math.min(x.total,Number(x.paid||0)+n);saveDB();render();toast('تم تسجيل الدفعة')}
function openDocumentWindow(){
 // Do not call window.open here: Android WebView can return a WindowProxy
 // even when the APK has no WebChromeClient.onCreateWindow implementation.
 // An in-page iframe is therefore the primary, deterministic preview surface.
 try{
  const old=document.getElementById('document-export-frame');
  if(old)old.remove();
  const frame=document.createElement('iframe');
  frame.id='document-export-frame';
  frame.title='معاينة المستند';
  frame.setAttribute('aria-label','معاينة المستند');
  frame.setAttribute('allow','clipboard-read; clipboard-write');
  frame.style.cssText='position:fixed;inset:0;width:100%;height:100%;border:0;background:#fff;z-index:2147483647;display:block';
  frame.setAttribute('sandbox','allow-same-origin allow-scripts allow-modals allow-downloads allow-forms');
  document.body.appendChild(frame);
  const w=frame.contentWindow;
  if(!w||!w.document)throw new Error('iframe document unavailable');
  w.document.open();
  return w;
 }catch(e){
  const frame=document.getElementById('document-export-frame');
  if(frame)frame.remove();
  console.error('Document preview failed:',e);
  if(typeof toast==='function')toast('تعذر تجهيز معاينة المستند. أغلق الصفحة وحاول مرة أخرى.');
  return null;
 }
}
function closeDocumentPreview(){const f=document.getElementById('document-export-frame');if(f)f.remove()}
