function saveSettings(e){e.preventDefault();let fd=new FormData(e.target);db.settings={...db.settings,shopName:fd.get('shopName'),phone:fd.get('phone'),currency:fd.get('currency')||'ر.ق',address:fd.get('address'),tax:Number(fd.get('tax')||0),language:db.settings.language||'ar'};saveDB();render();toast('تم حفظ إعدادات الورشة')}
function exportBackup(){db.settings.lastBackupAt=new Date().toISOString();saveDB();let backup=structuredClone(db);backup.settings.pinEnabled=false;delete backup.settings.pinHash;delete backup.settings.pinSalt;let blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='BoMansoor-Backup-'+dateNow()+'.json';a.click();document.body.appendChild(a);a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);render();toast('تم تجهيز النسخة الاحتياطية')}
function importBackup(){let f=document.getElementById('backupFile').files[0];if(!f){toast('اختر ملف النسخة الاحتياطية أولًا');return}if(!confirm('ستُستبدل البيانات الحالية بمحتويات النسخة. هل تريد المتابعة؟'))return;let r=new FileReader();r.onload=()=>{try{let obj=JSON.parse(r.result);if(!obj.customers||!obj.projects)throw new Error();const localSecurity={pinEnabled:db.settings.pinEnabled,pinHash:db.settings.pinHash,pinSalt:db.settings.pinSalt,autoLockMinutes:db.settings.autoLockMinutes};db={...structuredClone(defaultDB),...obj,settings:{...structuredClone(defaultDB.settings),...(obj.settings||{}),...localSecurity}};saveDB();render();toast('تمت استعادة النسخة بنجاح')}catch(e){toast('الملف غير صالح أو ليس نسخة ForgePro')}};r.readAsText(f)}
function exportCSV(collection){let arr=db[collection]||[];if(!arr.length){toast('لا توجد بيانات للتصدير');return}let keys=[...new Set(arr.flatMap(Object.keys))],csv=[keys.join(','),...arr.map(o=>keys.map(k=>'"'+String(o[k]??'').replace(/"/g,'""')+'"').join(','))].join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ForgePro-${collection}-${dateNow()}.csv`;a.click();URL.revokeObjectURL(a.href)}
function resetData(){if(!confirm('تحذير: سيتم حذف كل العملاء والمشاريع والفواتير والمخزون نهائيًا من هذا الجهاز. هل تريد المتابعة؟'))return;if(!confirm('تأكيد إضافي: هل أنشأت نسخة احتياطية حديثة وتريد حذف جميع البيانات؟'))return;const phrase=prompt('للتأكيد النهائي، اكتب كلمة حذف');if(phrase!=='حذف'){toast('تم إلغاء إعادة الضبط');return}const keepSecurity={pinEnabled:db.settings.pinEnabled,pinHash:db.settings.pinHash,pinSalt:db.settings.pinSalt,autoLockMinutes:db.settings.autoLockMinutes};db=structuredClone(defaultDB);db.settings={...db.settings,...keepSecurity};saveDB();render();toast('تمت إعادة ضبط البيانات')}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('quickAdd').addEventListener('click',()=>{const map={dashboard:'project',customers:'customer',projects:'project',quotes:'quote',production:'production',inventory:'inventory',purchases:'purchase',installations:'installation',invoices:'invoice',expenses:'expense'};openForm(map[currentPage]||'project')});
document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
